def load_config(uri):
    directory, filename = uri.rsplit("/", 1)

    file = next(
        f for f in mssparkutils.fs.ls(directory)
        if f.isFile and f.name == filename
    )

    return json.loads(mssparkutils.fs.head(uri, file.size))

def discover_source_files(config, dataset):
    source = dataset["source"]

    path = build_storage_path(
        config,
        source["layer"],
        source["directory"]
    )

    return [
        f for f in mssparkutils.fs.ls(path)
        if f.isFile and fnmatchcase(f.name, source["file_pattern"])

from pyspark.sql.types import StructType

def load_schema(config, dataset):
    path = build_storage_path(
        config,
        "config",
        f"{config['paths']['config']['schemas']}/{dataset['source']['schema_file']}"
    )

    return StructType.fromJson(load_config(path))
